frappe.ui.form.on('Student', {
  student_report:function(frm){
      if(frm.is_new()){
          frappe.msgprint("please save the student form");
          return;
      }
    frappe.set_route("print",frm.doctype,frm.doc.name);

  }
})

frappe.listview_settings["Student"] = {
    onload(listview) {
        frappe.msgprint("Student List Loaded");
    },

    get_indicator(doc) {
        if (doc.student_status === "Approved") {
            return ["Approved", "green", "student_status,=,Approved"];
        }

        if (doc.student_status === "Applied") {
            return ["Applied", "orange", "student_status,=,Applied"];
        }

        if (doc.student_status === "Rejected") {
            return ["Rejected", "red", "student_status,=,Rejected"];
        }

        return ["Draft", "gray", "student_status,=,Draft"];
    },

    button: {
        show(doc) {
            return true;
        },

        get_label() {
            return "Open Department";
        },

        get_description(doc) {
            return "Go to Student Department List";
        },

        action(doc) {
            frappe.set_route("List", "Student Department");
        }
    }
};

frappe.ui.form.on("Privacy Request", {

    refresh(frm) {

        if (!frm.is_new() && frm.doc.status != "Completed") {

            frm.add_custom_button("Process Privacy Request", function () {

                frappe.call({
                    method: "college_management.api.process_privacy_request",
                    args: {
                        docname: frm.doc.name
                    },
                    callback: function(r) {

                        frappe.msgprint(r.message);

                        frm.reload_doc();

                    }
                });

            });

        }

    }

});

frappe.ui.form.on("Student", {
    refresh(frm) {

        if (frm.is_new()) {
            return;
        }

        frm.add_custom_button("Get Student Info", function () {

            frappe.call({
                method: "student_management.student_management.doctype.student.student.get_student_info",
                args: {
                    student_name: frm.doc.name
                },
                callback: function (r) {
                    if (r.message) {
                        frappe.msgprint(r.message);
                    }
                }
            });

        });
    }
});

frappe.ui.form.on("Student", {
    refresh(frm) {

        frm.add_custom_button("Check Student Cache", function () {

            frappe.call({
                method: "student_management.cache.get_cached_student_count",

                callback: function(r) {

                    if (r.message) {
                        frappe.msgprint(
                            "Student Count: " + r.message.count +
                            "<br>Source: " + r.message.source
                        );
                    }

                }
            });

        });

    }
});

frappe.ui.form.on("Teacher", {
    refresh: function(frm) {
        frm.add_custom_button("Test Basic Msgprint", () => {
            frappe.call({ method: "student_management.api.test_basic" });
        });
    }
});

