frappe.ui.form.on('ToDo', {
    refresh(frm) {

        frm.call('get_linked_doc', {
            throw_if_missing: true
        }).then(r => {

            if (r.message) {

                const linked_doc = r.message;

                console.log(linked_doc);

            }

        });

    }
});

frappe.ui.form.on('Student', {

    refresh(frm) {

        console.log("Student form loaded");

        if (!frm.doc.student_group) {
            console.log("No Student Group selected");
            return;
        }

        frm.call('get_student_group', {
            throw_if_missing: true
        })
        .then(r => {

            console.log("Server response:", r);

            if (r.message) {

                const student_group = r.message;

                console.log(
                    "Student Group:",
                    student_group
                );

                frappe.msgprint(
                    `Student Group: ${student_group.name}`
                );
            }

        })
        .catch(error => {

            console.error(
                "Error calling Python:",
                error
            );

        });

    }

});
frappe.ui.form.on('Student', {

    refresh(frm) {
        frm.trigger('set_mandatory_fields');
    },

    set_mandatory_fields(frm) {

        frm.toggle_reqd(
            'student_email',
            frm.doc.student_status === 'Approved'
        );

    }

});

frappe.ui.form.on("Teacher", {
    refresh(frm) {
        frm.add_custom_button("Check Current Route", () => {
            let route = frappe.get_route();

            console.log(route);
        });
    }
});
frappe.ui.form.on("Teacher", {
    refresh(frm) {

        frm.add_custom_button("Show Formatted Salary", () => {

            let formatted_salary = frappe.format(frm.doc.salary, {
                fieldtype: "Currency"
            });

            // Remove spaces around the currency amount
            formatted_salary = formatted_salary.replace(/\s+/g, "");

            frappe.msgprint({
                title: "Teacher Salary",
                message: `
                    <b>Teacher:</b> ${frm.doc.teacher_name}<br>
                    <b>Salary:</b> ${formatted_salary}
                `
            });
        });

    }
});

frappe.ui.form.on("Teacher", {
    onload(frm) {
        const tour_name = "creating the teacher";

        frm.tour.init({ tour_name }).then(() => {
            frm.tour.start();
        });
    }
});

frappe.ui.form.on("Student Group", {
    onload(frm) {
        const tour_name = "student group tour";

        frm.tour.init({ tour_name }).then(() => {
            frm.tour.start();
        });
    }
});

frappe.ui.form.on("Teacher", {
    refresh(frm) {
        frm.add_custom_button("Create Task", () => {
            let dialog = new frappe.ui.Dialog({
                title: "Create Task",

                fields: [
                    {
                        label: "Task Subject",
                        fieldname: "task_subject",
                        fieldtype: "Data",
                        reqd: 1
                    }
                ],

                primary_action_label: "Create Task",

                primary_action(values) {
                    frappe.call({
                        method: "student_management.task_api.create_task",

                        args: {
                            task_subject: values.task_subject
                        },

                        callback(response) {
                            dialog.hide();

                            frappe.msgprint({
                                title: "Success",
                                message: `Task ${response.message} created successfully.`,
                                indicator: "green"
                            });
                        }
                    });
                }
            });

            dialog.show();
        });
    }
});

